/* Binary assets linked into the ELF; generated by tools/build_*.py. */
    .section .rodata
    .balign 32
    .global _rl_level_cascade_lvl
_rl_level_cascade_lvl:
    .incbin "assets/generated/level_cascade.lvl"

    .balign 32
    .global _rl_level_moab_lvl
_rl_level_moab_lvl:
    .incbin "assets/generated/level_moab.lvl"

    .balign 32
    .global _rl_level_dunes_lvl
_rl_level_dunes_lvl:
    .incbin "assets/generated/level_dunes.lvl"

    .balign 32
    .global _rl_level_lowland_lvl
_rl_level_lowland_lvl:
    .incbin "assets/generated/level_lowland.lvl"

    .balign 32
    .global _rl_outland_moab
_rl_outland_moab:
    .incbin "assets/generated/level_moab.out"

    .balign 32
    .global _rl_outland_dunes
_rl_outland_dunes:
    .incbin "assets/generated/level_dunes.out"

    .balign 32
    .global _rl_outland_lowland
_rl_outland_lowland:
    .incbin "assets/generated/level_lowland.out"

/* The sounds are copied to the sound chip's own memory at boot and never
   read here again, so their room is handed on (audio.c): in .data, as it
   is written to after that. The textures likewise, once the PVR has
   them (main.c, spent_alloc). */
    .section .data
    .balign 32
    .global _rl_textures_pak
_rl_textures_pak:
    .incbin "assets/generated/textures.pak"
    .global _rl_textures_pak_end
_rl_textures_pak_end:
    .balign 32
    .global _rl_sfx_pak
_rl_sfx_pak:
    .incbin "assets/generated/sfx.pak"
    .global _rl_sfx_pak_end
_rl_sfx_pak_end:
